def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)
    markers = [value for value in counts if value != background]
    marker = markers[0]

    for r in range(h):
        positions = [c for c in range(w) if grid[r][c] == marker]
        for left, right in zip(positions, positions[1:]):
            for c in range(left + 1, right):
                out[r][c] = 3

    for c in range(w):
        positions = [r for r in range(h) if grid[r][c] == marker]
        for top, bottom in zip(positions, positions[1:]):
            for r in range(top + 1, bottom):
                out[r][c] = 3
    return out
